import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*;
public class ContactFields extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x00425c70L,0x00425ef0L,0x004264c0L,0x00425800L};for(long x:xs){Function f=getFunctionAt(toAddr(x));println("\n=== "+toAddr(x)+" "+f+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,500,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());for(Reference rr:getReferencesTo(f.getEntryPoint())){Function c=getFunctionContaining(rr.getFromAddress());if(c!=null)println("CALLER "+rr.getFromAddress()+" "+c.getName());}}}d.dispose();}}
